Note that since $\Lambda_p$ is an elementary lattice (i.e.\ $\Lambda_p^*/\Lambda_p$ is an elementary $p$-group), Theorem $1.1(1)$ of Allcock \cite{allcock2025} tells us that $O(\Lambda_p)$ is maximal in $O(V_p)$ among the orthogonal groups of all $p$-adic lattices. Hence, if we can show that $O(\Lambda_p)\subseteq O(\Pi_p)$ then we will be done.

By standard arguments, there are exactly $p^2+p+1$ sublattices of $\Lambda_p$ of index $p$ up to change of basis. If $\Lambda_p$ has basis $\{v_1,v_2,v_3\}$ with respect to the above Gram matrix then these sublattices have bases \[\{pv_1,v_2,v_3\} \qquad \{v_1+\alpha v_2, pv_2, v_3\} \qquad \{v_1+\alpha v_3, v_2 + \beta v_3, pv_3\},\] with $\alpha,\beta\in \{0,1,...,p-1\}$, and corresponding Gram matrices: \[\begin{pmatrix}
p^2a & 0 & 0\\ 0 & p & 0\\ 0 & 0 & pb
\end{pmatrix}\qquad \begin{pmatrix}
a+p\alpha^2 & p^2\alpha & 0\\ p^2\alpha & p^3 & 0\\ 0 & 0 & pb
\end{pmatrix} \qquad \begin{pmatrix}
a+pb\alpha^2 & pb\alpha\beta & p^2b
\alpha\\ pb\alpha\beta & p(1+b\beta^2) & p^2b\beta\\ p^2b\alpha & p^2b\beta & p^3b
\end{pmatrix}.\] Note that the first Gram matrix corresponds to the lattice $\Pi_p$, and is visibly the only one having norm ideal $p\mathbb{Z}_p$. Now if $\gamma\in O(\Lambda_p)$ then $\gamma\Lambda_p = \Lambda_p$ and $\gamma\Pi_p$ is a sublattice of $\Lambda_p$ of index $p$. However, isometries preserve norm ideals and so we must have that $\gamma\Pi_p = \Pi_p$, i.e.\ $\gamma\in O(\Pi_p)$. This gives $O(\Lambda_p)\subseteq O(\Pi_p)$, as required.

\label{2-unimod}
Let $a,b,c\in\{\pm 1, \pm 5\}$ and let $\Delta = ab+ac+bc$. Suppose that $(V_2,Q)$ is a ternary quadratic space over $\mathbb{Q}_2$ containing a $2$-adic lattice $\Lambda_2\subset V_2$ with Gram matrix $\langle a,b,c\rangle$. Then the $2$-adic sublattice $\Pi_2\subset V_2$ of index $2$ with Gram matrix: \[\begin{pmatrix}
a+c & c & 2c\\ c & b+c & 2c\\ 2c & 2c & 4c    
\end{pmatrix}\sim\begin{cases}\left\langle\begin{pmatrix}
2 & 1\\ 1 & 2
\end{pmatrix}, 12abc\right\rangle & \text{ if } \Delta \equiv 3 \bmod 8\\ \left\langle\begin{pmatrix}
0 & 1\\ 1 & 0
\end{pmatrix},-4abc\right\rangle & \text{ if } \Delta \equiv 7 \bmod 8\end{cases}\] satisfies $O(\Lambda_2) = O(\Pi_2)$.

\label{2-mod} Let $a,b,c\in\{ \pm 1, \pm 5\}$ and $(V_2,Q)$ be a ternary quadratic space over $\mathbb{Q}_2$.
\begin{enumerate}[label = (\roman*)]
\item{Suppose that $(V_2,Q)$ contains a $2$-adic lattice $\Lambda_2\subset V_2$ with Gram matrix $\left\langle\begin{pmatrix}2 & 1 \\ 1 & 2\end{pmatrix},-2a\right\rangle$. Then the $2$-adic sublattice $\Pi_2\subset V_2$ of index $2$ with Gram matrix $\left\langle\begin{pmatrix}2 & 1 \\ 1 & 2\end{pmatrix},-8a\right\rangle$ satisfies $O(\Lambda_2) = O(\Pi_2)$.}
\item{Suppose that $(V_2,Q)$ contains a $2$-adic lattice $\Lambda_2\subset V_2$ with Gram matrix $\langle a,b,2c\rangle$. Then the $2$-adic sublattices $\Pi_2, \Omega_2\subset V_2$ of index $2$ with Gram matrices: 

\begin{align*}&\langle a,b+2c,8(c+2b)\rangle &&\langle a+2c,b,8(c+2a)\rangle &&\text{ if } a+b\equiv 0 \bmod 4\\ &\langle a,b,8c\rangle &&\langle a+2c,b+2c+4,8(c+2a+2b)\rangle &&\text{ if } a+b \equiv 2 \bmod 4\end{align*} satisfy $O(\Pi_2) = O(\Lambda_2) = O(\Omega_2)$.

Further, the $2$-adic sublattice $\Sigma_2\subset V_2$ with Gram matrix \[\begin{pmatrix}a+b & 2b & 0\\ 2b & 4b & 0\\ 0 & 0 & 2c\end{pmatrix} \sim \begin{cases}\langle-2c,-2c,-10c\rangle & \text{ if } a+b \equiv 0 \bmod 4 \text{ and } ab \equiv 3 \bmod 8\\ \langle2,-2,2c\rangle & \text{ if } a+b \equiv 0 \bmod 4 \text{ and } ab \equiv 7 \bmod 8\\ \langle 2a,2a,2c\rangle & \text{ if } a+b \equiv 2 \bmod 4 \text{ and } ab \equiv 1 \bmod 8\\ \langle -10a,-2a,2c\rangle & \text{ if } a+b \equiv 2 \bmod 4 \text{ and } ab \equiv 5 \bmod 8 \end{cases}\] satisfies $O(\Lambda_2) \subseteq O(\Sigma_2)$, with equality when any of the following conditions are satisfied: \begin{itemize}
\item{$a+b\equiv 0 \bmod 4$ and $ab\equiv 7 \bmod 8$,}
\item{$a+b\equiv 2 \bmod 4$, $ab\equiv 1 \bmod 8$ and $a\not\equiv c \bmod 4$,}
\item{$a+b\equiv 2 \bmod 4$, $ab\equiv 5 \bmod 8$ and $a\equiv c \bmod 4$.}
\end{itemize}}
\end{enumerate}

\begin{enumerate}[label = (\roman*)]
\item{Theorem $1.1(2)$ of Allcock \cite{allcock2025} shows that $O(\Lambda_2)$ is maximal in $O(V_2)$ among the orthogonal groups of all $2$-adic lattices. Hence it again suffices to show that $O(\Lambda_2) \subseteq O(\Pi_2)$.

Fix a basis $\{v_1,v_2,v_3\}$ for $\Lambda_2$ realising the Gram matrix above. The sublattices of $\Lambda_2$ of index $2$ then have bases: \[\{2v_1,v_2,v_3\}\qquad \{v_1+\alpha v_2,2v_2,v_3\}\qquad\{v_1+\alpha v_3, v_2 + \beta v_3, 2v_3\}\] with $\alpha,\beta\in\{0,1\}$ and corresponding Gram matrices:

\[\begin{pmatrix}
8 & 2 & 0\\ 2 & 2 & 0\\ 0 & 0 & -2a
\end{pmatrix}\qquad \begin{pmatrix} 2(1+\alpha+\alpha^2) & 2(1+2\alpha) & 0\\ 2(1+2\alpha) & 8 & 0\\ 0 & 0 & -2a
\end{pmatrix} \qquad \begin{pmatrix}
2(1-a\alpha^2) & 1-2a\alpha\beta & -4a\alpha\\ 1-2a\alpha\beta & 2(1-a\beta^2) & -4a\beta\\ -4a\alpha & -4a\beta & -8a
\end{pmatrix}.\] A simple calculation shows that the first lattice and the two lattices in the second family are all isometric (each Gram matrix is equivalent to $\langle 6,2,-2a\rangle$ over $\mathbb{Z}_2$). Similarly, the three lattices in the third family corresponding to $(\alpha,\beta) \neq (0,0)$ are all isometric (each Gram matrix is equivalent to $\left\langle\begin{pmatrix}0 & 1\\ 1 & 0\end{pmatrix},24a\right\rangle$ over $\mathbb{Z}_2$). 

The lattice corresponding to $(\alpha,\beta) = (0,0)$ has Gram matrix $\left\langle\begin{pmatrix}2 & 1\\ 1 & 2\end{pmatrix},-8a\right\rangle$, which is not isometric to any of the other index $2$ lattices, showing that $O(\Lambda_2) \subseteq O(\Pi_2)$, as required.}
\item{Fix a basis $\{v_1,v_2,v_3\}$ for $\Lambda_2$ realising the Gram matrix above. Then the sublattices of $\Lambda_2$ of index $2$ have bases: \[\{2v_1, v_2, v_3\}\qquad \{v_1+\alpha v_2,2v_2,v_3\}\qquad \{v_1+\alpha v_3, v_2 + \beta v_3, 2v_3\}\] with $\alpha,\beta\in\{0,1\}$ and corresponding Gram matrices: \[\begin{pmatrix}
4a & 0 & 0\\ 0 & b & 0\\ 0 & 0 & 2c
\end{pmatrix}\qquad \begin{pmatrix} a+b\alpha^2 & 2b\alpha & 0\\ 2b\alpha & 4b & 0\\ 0 & 0 & 2c
\end{pmatrix} \qquad \begin{pmatrix}
a+2c\alpha^2 & 2c\alpha\beta & 4c\alpha\\ 2c\alpha\beta & b+2c\beta^2 & 4c\beta\\ 4c\alpha & 4c\beta & 8c
\end{pmatrix}.\]

The first lattice and the second with $\alpha = 0$ give isometric lattices (either $a,b \equiv \pm 1 \bmod 8$ or $a,b\equiv \pm 5 \bmod 8$, in which case the lattices have equal Conway-Sloane $2$-adic symbol, otherwise they are related by two applications of the standard Sign Walking rule, see \cite{conway2013sphere} or \cite{allcock2020conway}). These lattices visibly have one-dimensional unimodular, $2$-modular and $4$-modular components.

The lattice $\Sigma_2$ comes from the second family with $\alpha = 1$. This lattice is even and all of the other lattices are visibly odd. It follows that $O(\Lambda_2) \subseteq O(\Sigma_2)$. To show that this lattice has Gram matrix equivalent to the diagonal ones given in the proposition we argue as follows:

\vspace{0.1in}
\noindent\textbf{Case 1:} If $a+b\equiv 2 \bmod 4$ then: \begin{align*}\begin{pmatrix}a+b & 2b & 0\\ 2b & 4b & 0\\ 0 & 0 & 2c\end{pmatrix} = 2\begin{pmatrix}\frac{a+b}{2} & b & 0\\ b & 2b & 0\\ 0 & 0 & c\end{pmatrix} &\sim 2\begin{pmatrix}\frac{a+b}{2} & 0 & 0\\ 0 & 2b-\frac{2b^2}{a+b} & 0\\ 0 & 0 & c\end{pmatrix}\\ &\sim \langle a+b,\,\, \frac{4ab}{a+b},\,\, 2c\rangle\\ &\sim\langle a+b,\,\, ab(a+b),\,\, 2c\rangle\end{align*} (since $\frac{2}{a+b}\in\mathbb{Z}_2^{\times}$). If $ab \equiv 1 \bmod 8$ then $b \equiv a \bmod 8$, giving $\langle 2a, 2a, 2c\rangle$. If $ab \equiv 5 \bmod 8$ then $b \equiv 5a \bmod 8$ and so this lattice is $\langle 6a, 30a, 2c\rangle \sim \langle -10a, -2a, 2c\rangle$.

\vspace{0.1in}
\noindent\textbf{Case 2:} If $a+b\equiv 0 \bmod 4$ then the $2\times2$ submatrix: \[\begin{pmatrix}a+b & 2b\\ 2b & 4b\end{pmatrix}\] is even unimodular of discriminant $[2ab]$. It follows that: \[\begin{pmatrix}a+b & 2b & 0\\ 2b & 4b & 0\\ 0 & 0 & 2c\end{pmatrix}\sim \begin{cases}\begin{pmatrix}0 & 2 & 0\\ 2 & 0 & 0\\ 0 & 0 & 2c\end{pmatrix} & \text{ if } ab \equiv 7 \bmod 8\\ \begin{pmatrix}4 & 2 & 0\\ 2 & 4 & 0\\ 0 & 0 & 2c\end{pmatrix} & \text{ if } ab \equiv 3 \bmod 8\end{cases}.\] It is well known that these lattices are isometric to $\langle -2c,-2c,-10c\rangle$ and $\langle 2,-2,2c\rangle$ respectively (since their Conway-Sloane 2-adic symbols satisfy $2^{+2}_{\text{II}}2^\varepsilon_c\sim 2^{(\varepsilon_c)3}$ and $2^{-2}_{\text{II}}2^{\varepsilon_c}_c \sim 2^{(-\varepsilon_c)3}_c$, by Oddity Fusion).

We now show that $O(\Sigma_2)\subseteq O(\Lambda_2)$, under the special conditions given in the proposition. Consider the seven superlattices of $\Sigma_2$. These have bases: \begin{align*}&\left\{\frac{v_1+v_2}{2},2v_2,v_3\right\}\qquad \left\{v_1+v_2,v_2-\frac{\alpha (v_1+v_2)}{2},v_3\right\} \\ &\left\{v_1+v_2,2v_2,\frac{v_3}{2}-\frac{\alpha(v_1+v_2)}{2}-\beta v_2\right\}\end{align*} with $\alpha,\beta\in\{0,1\}$ and Gram matrices: \begin{align*}&\begin{pmatrix}
\frac{a+b}{4} & b & 0\\ b & 4b & 0\\ 0 & 0 & 2c
\end{pmatrix}\qquad \begin{pmatrix} a+b & -\frac{a\alpha}{2}+b\left(1-\frac{\alpha}{2}\right) & 0\\ -\frac{a\alpha}{2}+b\left(1-\frac{\alpha}{2}\right) & \frac{a\alpha^2}{4}+b\left(1-\frac{\alpha}{2}\right)^2 & 0\\ 0 & 0 & 2c
\end{pmatrix} \\ &\begin{pmatrix}
a+b & 2b & -\frac{a\alpha}{2}-b\left(\frac{\alpha}{2}+\beta\right)\\ 2b & 4b & -b(\alpha+2\beta)\\ -\frac{a\alpha}{2}-b\left(\frac{\alpha}{2}+\beta\right) & -b(\alpha+2\beta) & \frac{c}{2}+\frac{a\alpha^2}{4}+b\left(\frac{\alpha}{2}+\beta\right)^2
\end{pmatrix}.\end{align*} A very lengthy brute force calculation shows that when we have one of the following conditions: \begin{itemize}
\item{$a+b\equiv 0 \bmod 4$ and $ab\equiv 7 \bmod 8$,}
\item{$a+b\equiv 2 \bmod 4$, $ab\equiv 1 \bmod 8$ and $a\not\equiv c \bmod 4$,}
\item{$a+b\equiv 2 \bmod 4$, $ab\equiv 5 \bmod 8$ and $a\equiv c \bmod 4$}
\end{itemize} the lattice $\Lambda_2$ is unique up to isometry in this list (and in all other cases there are repetitions). This proves that $O(\Sigma_2)\subseteq O(\Lambda_2)$ in these cases, so that we have equality.

We now consider the four lattices from the third family. After another tedious calculation we find that the Gram matrices are equivalent to the following over $\mathbb{Z}_2$: \begin{align*}&\langle a,b,8c\rangle\\ &\langle a,b+2c,8(c+2b)\rangle\\ &\langle b,a+2c,8(c+2a)\rangle\\ &\langle a+2c,b+2c+4,8(c+2a+2b)\rangle\end{align*} and one sees that all have a two-dimensional unimodular component and a one-dimensional $8$-modular component (hence cannot be isometric to any of the previously considered lattices). 

When $a+b \equiv 0  \bmod 4$, we see that lattices one and four in this list are isometric (using the Oddity Fusion rule, see \cite{conway2013sphere} or \cite{allcock2020conway}), but that lattices two and three are unique up to isometry in the list. When $a+b \equiv 2 \bmod 4$ one instead finds that the lattices two and three are isometric but that lattices one and four are unique up to isometry in the list. In either case, these are the two lattices $\Pi_2,\Omega_2$ given in the statement of the proposition, and the uniqueness of Gram matrix up to isometry once again proves that $O(\Lambda_2)\subseteq O(\Pi_2)$ and $O(\Lambda_2) \subseteq O(\Omega_2)$.

In order to prove the reverse inclusion, consider the generic lattice in this family, i.e.\ the lattice with basis $\{v_1+\alpha v_3, v_2+\beta v_3, 2v_3\}$. There are seven superlattices of index $2$, having bases: \begin{align*}&\left\{\frac{v_1+\alpha v_3}{2},v_2+\beta v_3, 2v_3\right\} \qquad \left\{v_1 + \alpha v_3, \frac{v_2+\beta v_3}{2}-\frac{\gamma (v_1+\alpha v_3)}{2},2v_3\right\}\\ &\left\{v_1+\alpha v_3, v_2+\beta v_3, v_3 - \frac{\gamma(v_1+\alpha v_3)}{2}-\frac{\delta(v_2+\beta v_3)}{2}\right\}\end{align*} with $\gamma,\delta\in\{0,1\}$ and Gram matrices: \begin{align*}&\begin{pmatrix}
\frac{a+2c\alpha^2}{4} & c\alpha\beta & 2c\alpha\\ c\alpha\beta & b+2c\beta^2 & 4c\beta\\ 2c\alpha & 4c\beta & 8c
\end{pmatrix}\qquad \begin{pmatrix}
a+2c\alpha^2 & -\frac{a\gamma}{2}+c\alpha(\beta-\alpha\gamma) & 4c\\ -\frac{a\gamma}{2}+c\alpha(\beta-\alpha\gamma) & \frac{b}{4}+\frac{a\gamma^2+c(\beta-\alpha\gamma)^2}{2} & 2c(\beta-\alpha\gamma)\\ 4c & 2c(\beta-\alpha\gamma) & 8c
\end{pmatrix}\\ &\begin{pmatrix}
a+2c\alpha^2 & 2c\alpha\beta & -\frac{a\gamma}{2} - c\alpha(\alpha\gamma+\beta\delta-2)\\ 2c\alpha\beta & b+2c\beta^2 & -\frac{b\delta}{2}-c\beta(\alpha\gamma+\beta\delta-2)\\ -\frac{a\gamma}{2} - c\alpha(\alpha\gamma+\beta\delta-2) & -\frac{b\delta}{2}-c\beta(\alpha\gamma+\beta\delta-2) & \frac{a\gamma^2+b\delta^2}{4} + 2c\left(1-\frac{\alpha\gamma+\beta\delta}{2}\right)^2
\end{pmatrix}\end{align*} It is immediate that the Gram matrix corresponding to $(\gamma,\delta) = (0,0)$ is the only one that is integral (this lattice being isometric to the original lattice $\Lambda_2$). It follows that $O(\Pi_2)\subseteq O(\Lambda_2)$ and $O(\Omega_2)\subseteq O(\Lambda_2)$, so that equality follows in all of the relevant cases.}
\end{enumerate}

\label{2-misc}
Let $(V_2,Q)$ be a ternary quadratic space over $\mathbb{Q}_2$.

\begin{enumerate}[label = (\roman*)]
\item{Suppose that $(V_2,Q)$ contains a $2$-adic lattice $\Lambda_2\subset V_2$ with Gram matrix $\langle 1,-1,-2\rangle$. Then there exist $2$-adic sublattices $\Pi_2,\Omega_2\subset V_2$ of index $2$ with Gram matrices $\langle 1,-2,-4\rangle$ and $\langle 1,-1,-8\rangle$ and satisfying $O(\Pi_2) = O(\Omega_2)$.}
\item{Suppose that $(V_2,Q)$ contains a $2$-adic lattice $\Lambda_2\subset V_2$ with Gram matrix $\langle 1,1,2\rangle$. Then there exist $2$-adic sublattices $\Pi_2,\Omega_2\subset V_2$ of index $2$ with Gram matrices $\langle 1,2,4\rangle$ and $\langle 1,-5,-40\rangle$ satisfying $O(\Pi_2) = O(\Omega_2)$.}
\end{enumerate}

In each case, fix a basis $\{v_1,v_2,v_3\}$ for $\Lambda_2$ realising the corresponding Gram matrix.
\begin{enumerate}[label = (\roman*)]
\item{We may take $\Pi_2$ to be the lattice with basis $\{v_1,2v_2,v_3\}$ and $\Omega_2$ to be the lattice with basis $\{v_1,v_2,2v_3\}$. Consider the common index $2$ sublattice $\Sigma_2$ with basis $\{v_1,2v_2,2v_3\}$ and Gram matrix $\langle 1,-4,-8\rangle$. A similar calculation to those above shows that $\Sigma_2$ is the unique index sublattice of $\Pi_2$ with Gram matrix isometric to $\langle 1,-4,-8\rangle$, so that $O(\Pi_2)\subseteq O(\Sigma_2)$. Similarly we find that $O(\Omega_2)\subseteq O(\Sigma_2)$.

To show the converse, we compute the superlattices of $\Sigma_2$ of index $2$. There are once again seven of these, having bases \[\left\{\frac{1}{2}v_1,2v_2,2v_3\right\}\qquad \left\{v_1, v_2 - \frac{\alpha}{2}v_1,2v_3\right\}\qquad \left\{v_1, 2v_2, v_3-\frac{\alpha}{2}v_1-\beta v_2\right\}\] with $\alpha,\beta\in\{0,1\}$ and corresponding Gram matrices:\[\begin{pmatrix}
\frac{1}{4} & 0 & 0\\ 0 & -4 & 0\\ 0 & 0 & -8
\end{pmatrix}\qquad \begin{pmatrix} 1 & -\frac{\alpha}{2} & 0\\ -\frac{\alpha}{2} & -1+\frac{\alpha^2}{4} & 0\\ 0 & 0 & -8
\end{pmatrix} \qquad \begin{pmatrix}
1 & 0 & -\frac{\alpha}{2}\\ 0 & -4 & 2\beta\\ -\frac{\alpha}{2} & 2\beta & -2+\frac{\alpha^2}{4}-\beta^2
\end{pmatrix}.\] The lattices corresponding to $\alpha = 0$ and $(\alpha,\beta) = 0$ correspond to $\Omega_2$ and $\Pi_2$ respectively and it can be checked that these Gram matrices are unique up to isometry in this list. This proves that $O(\Sigma_2)\subseteq O(\Pi_2)$ and $O(\Sigma_2)\subseteq O(\Omega_2)$, so that the desired equality now follows.}
\item{We may take $\Pi_2$ to be the lattice with basis $\{v_1,2v_2,v_3\}$ and $\Omega_2$ to be the lattice with basis $\{v_1+v_3,v_2,2v_3\}$ (giving two Gram matrices that are equivalent to $\langle 1,2,4\rangle$ and $\langle 1,-5,-40\rangle$ over $\mathbb{Z}_2$). Consider the common index $2$ sublattice $\Sigma_2$ with basis $\{v_1+v_3,2v_2,2v_3\}$ and Gram matrix \[T = \begin{pmatrix}3 & 0 & 4\\ 0 & 4 & 0\\ 4 & 0 & 8\end{pmatrix}.\] The same argument as (i) then shows that $O(\Pi_2) = O(\Sigma_2) = O(\Omega_2)$ (i.e.\ $\Sigma_2$ is unique up to isometry in the list of index $2$ sublattices of $\Pi_2$ and $\Omega_2$, and $\Pi_2, \Omega_2$ are unique up to isometry in the list of index $2$ superlattices of $\Sigma_2$).}
\end{enumerate}

\label{4-mod}
Let $a\in\{\pm 1,\pm 5\}$. Suppose that $(V_2,Q)$ is a ternary quadratic space over $\mathbb{Q}_2$ containing a $2$-adic lattice $\Lambda_2\subset V_2$ with Gram matrix $\left\langle\begin{pmatrix}
0 & 1\\ 1 & 0
\end{pmatrix},-4a\right\rangle$. Then the $2$-adic sublattice $\Pi_2\subset V_2$ with Gram matrix $\langle 2,-2,-4a\rangle$ satisfies $O(\Lambda_2) = O(\Pi_2)$.

Consider the lattices $\Lambda$ and $\Sigma$ with Gram matrices
\begin{align*}
    T_{\Lambda} = \begin{pmatrix} 1& 0 & 0 \\ 0& 11 & 0 \\ 0& 0& 22
    \end{pmatrix} \quad \text{and} \quad & T_{\Sigma} = \begin{pmatrix} 2& 0 & 0 \\ 0& 4 & 2 \\ 0& 2& 12
    \end{pmatrix}
\end{align*}
and discriminants $\text{disc}(\Lambda) = 242 = 2\cdot 11^2$ and $\text{disc}(\Sigma) = 88 = 8\cdot 11$ respectively. It is easily checked that these lattices match the description of the two lattices of interest. A quick computation reveals that $|\text{Cl}(\Lambda)| = 2$ and $|\text{Cl}(\Sigma)| = 1$, showing that $O(\widehat{\Lambda}) \neq O(\widehat{\Sigma})$ (the issue must then be that $O(\Lambda_2) \neq O(\Sigma_2)$ since the local orthogonal groups are equal at all other primes). Further computation reveals that the characteristic polynomial of $T_p$ acting on the second class set always divides the one coming from the action on the first class set, in agreement with the embedding above.

\label{Example genus C and D disc 8}

Consider the odd lattice $\Lambda$ with Gram matrix \[ T = \begin{pmatrix}
    1 & 0 & 0 \\
    0 & 1 & 0 \\
    0 & 0 & 8
\end{pmatrix}\] representing Genus D. We have that $\text{Cl}(\Lambda) = \{[\Lambda]\}$ and so there is no modular data to be found at trivial weight (which fits with $S_2^{2\text{-new}}(\Gamma_0(4)) = \{0\}$). However, at weight $W_8$ we find that $\text{dim}(\mathcal{S}(O(V),O(\widehat{\Lambda}),W_8)) = 2$, and the characteristic polynomials of $T_p$ (for $p \neq 2$) have linear factors $F_{p,1}(x)$ and $F_{p,2}(x)$ as follows:

\vspace{0.1in}
\begin{tabular}{l l l l l}
			 $F_{3,1}(x) = x + 156$&\quad $F_{5,1}(x) = x-870$&\quad $F_{7,1}(x) = x+952$ &\quad $\dots$ \\
		$F_{3,2}(x) = x - 228$&\quad  $F_{5,2}(x) = x + 666$&\quad $F_{7,2}(x) = x + 6328$&\quad $\dots$
		\end{tabular}
\vspace{0.1in}

\noindent These match with the newforms $f \in S_{10}^{\text{new}}(\Gamma_0(2))$ and $g \in S_{10}^{\text{new}}(\Gamma_0(4))$ having LMFDB labels \href{https://www.lmfdb.org/ModularForm/GL2/Q/holomorphic/2/10/a/a/}{2.10.a.a} and \href{https://www.lmfdb.org/ModularForm/GL2/Q/holomorphic/4/10/a/a/}{4.10.a.a} and Fourier expansions: 

\begin{align*}
    f(q) &=q + 16q^2 - 156q^3 + 256q^4 + 870q^5 - 2496q^6 - 952q^7 + \dots  \\
    g(q) &= q + 228 q^3 - 666 q^5 - 6328 q^7 + 32301 q^9 - 30420 q^{11}  \dots
\end{align*} The newforms above are precisely those of level $4$ that are $2$-new and have Atkin-Lehner sign $-1$, as expected from Conjecture \ref{genusCD}.

Consider the odd lattice with Gram matrix \[ T = \begin{pmatrix}
    1 & 0 & 0 \\
    0 & 2 & 0 \\
    0 & 0 & 4
\end{pmatrix}\] representing Genus B. Again,  $\text{Cl}(\Lambda) = \{[\Lambda]\}$ and so no modular data is found at trivial weight (which agrees with the fact that $S_2^{2\text{-new}}(\Gamma_0(8)) = \{0\}$). At weight $W_8$ we find that $\text{dim}(\mathcal{S}(O(V),O(\widehat{\Lambda}),W_8)) = 3$. The characteristic polynomials of the Hecke operators $T_p$ (with $p\neq 2$) decompose into linear factors $F_{p,1}(x)$, $F_{p,2}(x)$ and $F_{p,3}(x)$ where the first two are the forms $f$ and $g$ with LMFDB labels \href{https://www.lmfdb.org/ModularForm/GL2/Q/holomorphic/2/10/a/a/}{2.10.a.a} and \href{https://www.lmfdb.org/ModularForm/GL2/Q/holomorphic/4/10/a/a/}{4.10.a.a} from Example \ref{Example genus C and D disc 8}. The third linear factor is given by:

\vspace{0.1in}
\begin{tabular}{l l l l l}
			$F_{3,3}(x) = x - 68$& $F_{5,3}(x) = x-1510$& $F_{7,3}(x) = x-10248$ & $\dots$ 
		\end{tabular}
\vspace{0.1in}

\noindent which is identified as the newform $h\in S_{10}^{\text{new}}(\Gamma_0(8))$ with LMFDB label
        \href{https://www.lmfdb.org/ModularForm/GL2/Q/holomorphic/8/10/a/b/}{8.10.a.b} and Fourier expansion:
$$f(q) = q + 68q^3 + 1510q^5 + 10248q^7 - 15059q^9 - 3916q^{11} + 176594q^{13} +\dots $$

All three forms observed are precisely those predicted by Conjecture \ref{conjBE} (in particular all have Atkin-Lehner eigenvalue $-1$). The other forms with Atkin-Lehner eigenvalue $+1$ are not seen in this calculation (but would be seen if we twist the weight by $\theta_2$).

\label{genus1b2acd}
Let $\Lambda$ be a lattice representing Genus $1$\textup{B}, Genus $2$\textup{A} or any of the genera of type \textup{C} or \textup{D}, and let $N$ denote the numeric part of the genus label. Then for each representation $W$ of $V$ there is an equality of Hecke modules: \[\mathcal{S}(O(V),O(\widehat{\Lambda}),W) = \mathcal{S}(O(V),O(\widehat{\Pi}),W),\] where $\Pi$ is a lattice of discriminant $2p^2$ representing Genus $N$.

In particular, for each $k\geq 0$ and $d\in\{1,2,p,2p\}$ we have the following Hecke-equivariant isomorphisms (for the algebra generated by the Hecke operators $T_q$ with $q\neq 2,p$ prime): \[\mathcal{S}(O(V),O(\widehat{\Lambda}),W_{2k}\otimes \theta_d)\cong \begin{cases}S^{\textup{new}}_{2k+2}\left(\Gamma_0(p),\varepsilon^{(p)}_p\varepsilon^{(p)}_d\right) & \text{ if } \Lambda\sim 1\textup{B}\\ S^{p\textup{-new}}_{2k+2}\left(\Gamma_0(2p),\varepsilon^{(2p)}_p\varepsilon^{(2p)}_d\right) & \text{ if } \Lambda\sim 2\textup{A},2\textup{C},2\textup{D}\\ S_{2k+2}^{2\textup{-new}}\left(\Gamma_0(4p),\varepsilon^{(4p)}_2\varepsilon^{(4p)}_d\right) & \text{ if } \Lambda\sim 3\textup{C},3\textup{D}\\ S^{2\textup{-new}}_{2k+2}\left(\Gamma_0(4p^2),\varepsilon_2^{(4p^2)}\varepsilon_d^{(4p^2)}\right) & \text{ if } \Lambda\sim 4\textup{C},4\textup{D}\\ S^{2\textup{-new}}_{2k+2}\left(\Gamma_0(4),\varepsilon^{(4)}_2\varepsilon^{(4)}_d\right)\oplus S^{2p^2\textup{-new}}_{2k+2}\left(\Gamma_0(4p^2),\varepsilon^{(4p^2)}_2\varepsilon^{(4p^2)}_d\right) & \text{ if } \Lambda\sim 5\textup{C},5\textup{D}\end{cases}\] where we have assumed Conjectures \ref{genus3}, \ref{genus4} and \ref{genus5} for the last three isomorphisms.

\label{3a4a5a}
Let $\Lambda$ be a lattice representing Genus $3$\textup{A}, Genus $4$\textup{A} or Genus $5$\textup{A}. Then for each representation $W$ of $V$ there is an equality of Hecke modules: \[\mathcal{S}(O(V),O(\widehat{\Lambda}),W) = \mathcal{S}(O(V),O(\widehat{\Pi}),W),\] where $\Pi$ is a suitable even lattice of discriminant $4p^2$ in $(V,Q^{\left(\frac{1}{2}\right)})$.

In particular, for each $k\geq 0$ and $d\in\{1,2,p,2p\}$ we have the following Hecke-equivariant isomorphisms (for the algebra generated by the Hecke operators $T_q$ with $q\neq 2,p$ prime): \[\mathcal{S}(O(V),O(\widehat{\Lambda}),W_{2k}\otimes \theta_d)\cong \begin{cases}S^{2\textup{-new}}_{2k+2}\left(\Gamma_0(2p),\varepsilon^{(2p)}_2\varepsilon^{(2p)}_d\right) & \text{ if } \Lambda\sim 3\textup{A}\\ S^{2\textup{-new}}_{2k+2}\left(\Gamma_0(2p^2),\varepsilon^{(2p^2)}_2\varepsilon^{(2p^2)}_d\right) & \text{ if } \Lambda\sim 4\textup{A}\\ S^{\textup{new}}_{2k+2}\left(\Gamma_0(2),\varepsilon^{(2)}_2\varepsilon^{(2)}_d\right)\oplus S^{\textup{new}}_{2k+2}\left(\Gamma_0(2p^2),\varepsilon^{(2p^2)}_2\varepsilon^{(2p^2)}_d\right) & \text{ if } \Lambda\sim 5\textup{A}\end{cases}\]

\label{genus3be}
Let $\Lambda$ be a lattice representing Genus $3$\textup{B}. Then for each $k\geq 0$ and $d\in\{1,2,p,2p\}$ we have the following Hecke-equivariant isomorphisms (for the algebra generated by the Hecke operators $T_q$ with $q\neq 2,p$ prime): 
\[\mathcal{S}(O(V),O(\widehat{\Lambda}),W_{2k}\otimes \theta_d)\cong S^{2\textup{-new}}_{2k+2}\left(\Gamma_0(4p),\varepsilon^{(4p)}_2\varepsilon^{(4p)}_d\right)\oplus S_{2k+2}^{8\textup{-new}}\left(\Gamma_0(8p),\varepsilon_2^{(8p)}\varepsilon_d^{(8p)}\right).\]

\label{genus4be}
Let $\Lambda$ be a lattice representing Genus $4$\textup{B}. Then for each $k\geq 0$ and $d\in\{1,2,p,2p\}$ we have the following Hecke-equivariant isomorphisms (for the algebra generated by the Hecke operators $T_q$ with $q\neq 2,p$ prime): 
\[\mathcal{S}(O(V),O(\widehat{\Lambda}),W_{2k}\otimes \theta_d)\cong S^{2\textup{-new}}_{2k+2}\left(\Gamma_0(4p^2),\varepsilon^{(8)}_2\varepsilon^{(8)}_d\right)\oplus S^{8\textup{-new}}_{2k+2}\left(\Gamma_0(8p^2),\varepsilon^{(8p^2)}_2\varepsilon^{(8p^2)}_d\right).\]

\label{genus5be}
Let $\Lambda$ be a lattice representing Genus $5$\textup{B}. Then for each $k\geq 0$ and $d\in\{1,2,p,2p\}$ there exists a Hecke-equivariant isomorphism (for the algebra generated by the Hecke operators $T_q$ with $q\neq 2,p$ prime) so that:
\begin{align*}\mathcal{S}(O(V),O(\widehat{\Lambda}),W_{2k}\otimes \theta_d) &\cong S_{2k+2}^{\textup{new}}\left(\Gamma_0(2),\varepsilon_2^{(2)}\varepsilon_d^{(2)}\right)&&\oplus S_{2k+2}^{4\textup{-new}}\left(\Gamma_0(8),\varepsilon_2^{(8)}\varepsilon_d^{(8)}\right)\\ &\oplus S_{2k+2}^{\textup{new}}\left(\Gamma_0(2p^2),\varepsilon_2^{(2p^2)}\varepsilon_d^{(2p^2)}\right)&&\oplus S_{2k+2}^{4p^2\textup{-new}}\left(\Gamma_0(8p^2),\varepsilon_2^{(8p^2)}\varepsilon_d^{(8p^2)}\right).\end{align*}
